<template>
  <DocumentLock
    v-if="record && record.document_version"
    :document_version="record.document_version"
    :trigger_document_lock="trigger_document_lock"
    :doc_id="docId"
    @setTriggerDocumentLock="setTriggerDocumentLock"
  />
  <MessageBanner
    v-if="is_view_readonly && !trigger_document_lock"
    :message="error_message"
    :messageCategoryClass="bannerBg"
  />
  <SubHeader
    name="quote_details"
    :label="$t('quote_details')"
    :show_expiry_alert="true"
    :onSearch="false"
  />

  <div class="row">
    <div class="col-12 q-pl-sm q-mt-sm">
      <!-- Start of section -->
      <div class="row" v-if="doc_fetch_error">
        <ErrorDocumentView />
      </div>
      <div class="row" v-else>
        <div :class="rightSectionClass" id="right_section" ref="right_section">
        <q-splitter
          :limits="[30, 100]"
          v-model="imageFieldSplitter"
          class="height-100vh-115px"
          @update:model-value="splitterChanged()"
        >
          <template v-slot:before>
            <div
              class="h-m-r-10"
              id="po-container-parrent"
              style="border-right: 1px solid #9f9d9d"
            >
              <div class="row">
                <div class="po-nav-width q-pr-md row">
                  <div class="q-mr-auto q-mt-sm">
                    <q-btn flat rounded color="primary" @click="routeToBack()">
                      <Icon icon="mdi:arrow-left-circle" width="20" height="20" />
                      <label
                        style="
                          vertical-align: middle;
                          margin-left: 10px;
                          font-size: 20px;
                          cursor: pointer;
                        "
                        >{{ $t('back') }}</label
                      >
                    </q-btn>
                  </div>

                  <div class="q-ml-auto q-mt-sm">
                    <template v-if="!is_view_readonly">
                      <TaskBtn
                        :is_f_btn="true"
                        @btnClicked="gotoTaskPendingList()"
                      />
                      <CreateTaskBtn :is_icon_button="true" />
                    </template>

                    <exportBtns v-if="!is_view_readonly" />
                  </div>
                </div>
              </div>

              <div class="row ml-10 height-100vh-165px scrolle-y">
                <div class="col-sm-12">
                  <!-- separator -->
                  <div class="full-width">
                    <!-- Header -->

                    <div
                      class="row q-mt-md q-mb-md input-text-28px"
                      v-if="
                        documentFieldsConfig && documentFieldsConfig.length > 0
                      "
                    >
                      <template
                        v-for="(field, index) in documentFieldsConfig"
                        :key="index"
                      >
                        <div class="col-sm-4 col-md-4 col-lg-4 q-pa-sm">
                          <div class="row">
                            <div class="col-sm-12 col-md-12 col-lg-12">
                              {{ getFieldLabelFromAllPrefixes(field) }}
                            </div>
                            <div class="col-sm-12 col-md-12 col-lg-12">
                              <q-input
                                outlined
                                dense
                                v-model="
                                  documentFields[field.field_name]
                                    .formatted_value
                                "
                                :disable="true"
                              />
                            </div>
                          </div>
                        </div>
                      </template>
                    </div>

                    <q-separator />

                    <div class="full-width q-pt-md">
                      <LineItems
                        :isReadOnly="is_view_readonly"
                        :defaultValues="defalutAttributes"
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </template>

          <template v-slot:separator>
            <div style="margin-left: -13px; top: 10px">
              <q-btn
                round
                unelevated
                size="xs"
                :icon="
                  imageFieldSplitter >= 90 ? 'chevron_left' : 'chevron_right'
                "
                class="panel-expand-button highlighted-back shadow-2"
                @click="toggleImageArea()"
              />
            </div>

            <div style="margin-left: -5.5px; top: 40%">
              <q-icon
                name="drag_handle"
                size="md"
                class="icon-grey rotate-90"
              />
            </div>
          </template>

          <template v-slot:after>
            <div class="row">
              <div class="q-mt-sm scrolle-y" id="po-image-container" style="width: calc(100% - 40px); overflow: auto">
                <div id="image_container">
                  <img
                    v-if="record.images && record.images[page - 1]"
                    :src="baseUrl + '/' + record.images[page - 1].path + '?' + tokenQueryParam"
                    class="shadow-5 center-inner v-m-10 image-item"
                    style="width: 100%"
                    :style="{ transform: 'scale(' + imageZoom + ')', transformOrigin: 'top left' }"
                  />
                </div>
              </div>

              <!-- Action Bar -->
              <div class="column justify-between right-action-bar back-white height-100vh-115px" style="width: 40px">
                <div class="action-bar-items">
                  <q-btn
                    flat
                    class="validation-view-button v-p-0"
                    @click="openImageInSeparateWindow"
                  >
                    <Icon icon="mdi:fullscreen" width="20" height="20" />
                    <q-tooltip style="white-space: nowrap">{{ $t('open_image') }}</q-tooltip>
                  </q-btn>

                  <SidebarActionButtons
                    @toggleSidebar="toggleSideBar"
                  />
                  <q-separator class="separator-space" />
                </div>
                <div class="action-bar-bottom">
                  <q-separator class="q-mb-sm" />
                  <div class="q-my-auto">
                    <q-btn
                      flat
                      class="validation-view-button icon-grey"
                      @click="toggleSideBar('pages')"
                    >
                      <Icon icon="mdi:file-multiple" width="20" height="20" />
                      <q-tooltip>
                        {{ page }} / {{ record.images ? record.images.length : 0 }}
                      </q-tooltip>
                    </q-btn>
                  </div>
                  <q-input
                    outlined
                    dense
                    v-model="page"
                    class="validation-view-input"
                    @update:model-value="(val: any) => { scrollToPage(val) }"
                    @blur="validatePageNumber"
                  ></q-input>
                  <span class="validation-view-button q-pt-md">{{
                    record.images ? record.images.length : 0
                  }}</span>
                  <div>
                    <q-btn
                      :disable="page <= 1"
                      icon="keyboard_arrow_up"
                      flat
                      class="validation-view-page-button icon-grey"
                      @click="prevPage"
                    />
                    <q-btn
                      :disable="!record.images || page >= record.images.length"
                      icon="keyboard_arrow_down"
                      flat
                      class="validation-view-page-button icon-grey"
                      @click="nextPage"
                    />
                  </div>
                </div>
              </div>
            </div>
          </template>
        </q-splitter>
        </div>

        <div :class="[sidebarWidthClass, 'height-100vh-165px', { hidden: current_sidebar === '' }]" id="left_section" ref="left_section">
          <div class="scrolle-y full-height" v-if="current_sidebar == 'pages'">
            <div class="row justify-center q-pl-md q-pr-md q-pt-md">
              <span class="secondary-c-text text-h6 text-weight-bold">
                {{ $t('page_number_text') }}
              </span>
            </div>
            <div class="row">
              <div class="page-numbers center-inner">
                {{ page }}/{{ record.images ? record.images.length : 0 }}
              </div>
            </div>
            <div class="full-width scrolle-y pages-section-padding row justify-center">
              <img
                v-for="(imageMoc, index) in record.images"
                :key="index"
                :src="baseUrl + '/' + imageMoc.path + '?' + tokenQueryParam"
                class="q-pa-xs shadow-5 max-width-120 q-ma-sm cursor-pointer"
                :class="index === page - 1 ? 'active' : ''"
                style="height: 160px"
                @click="page = index + 1"
              />
            </div>
          </div>
          <SidebarPanel
            :currentSidebar="current_sidebar"
            :docId="docId"
          />
        </div>
      </div>
      <!-- End of section -->
    </div>
  </div>

  <q-inner-loading class="main-loader" :showing="processing" style="z-index: 2">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>

  <DocumentFooter
    :filename="record.filename"
    :docId="docId"
    v-model="imageZoom"
  >
    <span class="footer-status-message">{{ $t('quote_details') }}</span>
  </DocumentFooter>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { storeToRefs } from 'pinia';
import stringUtil from 'src/utils/string';
import { Acl } from 'src/core/acls/index';
import { defineComponent, ref } from 'vue';
import { DOC2API_URL } from 'src/pages/APIs';
import { CONSTANTS } from 'src/constants';
import { $, type dynamicObj } from 'src/pages/assets';
// import docTypeLable from 'src/utils/docTypeLable';
import { documentDetailApiService } from 'src/services';
import CreateTaskBtn from 'src/pages/Tasks/CreateBtn.vue';
import DocumentLock from 'src/components/DocumentLock.vue';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import MessageBanner from 'src/components/MessageBanner.vue';
import MaterialIconSet from 'quasar/icon-set/material-icons';
import LineItems from 'src/pages/QuoteDetails/LineItems.vue';
import SidebarPanel from 'src/components/document/SidebarPanel.vue';
import SidebarActionButtons from 'src/components/document/SidebarActionButtons.vue';
import DocumentFooter from 'src/components/document/DocumentFooter.vue';
import { useSidebarPanel } from 'src/composables/useSidebarPanel';
import { useImageAuth } from 'src/composables/useImageAuth';
import TaskBtn from 'src/components/document/Tasks/TaskBtn.vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import ErrorDocumentView from 'src/pages/Errors/ErrorDocumentView.vue';
import exportBtns from 'src/pages/PurchaseOrders/components/exportBtns.vue';
import {
  useDocumentStore,
  useDocLockStore,
  useTaskStore,
} from 'src/store/main';

MaterialIconSet.table.arrowUp = 'arrow_drop_down';

export default defineComponent({
  el: '#app',
  mixins: [stringUtil, displayFieldLabel],
  components: {
    
    TaskBtn,
    SubHeader,
    LineItems,
    exportBtns,
    DocumentLock,
    CreateTaskBtn,
    MessageBanner,
    SidebarPanel,
    SidebarActionButtons,
    DocumentFooter,
    ErrorDocumentView,
  },
  data() {
    return {
      docId: '',
      page: 1,
      error_message: '',
      dynamicWidth: ref(0),
      imageZoom: 1,
      imageFieldSplitter: ref(76),
      defalutAttributes: ref({} as dynamicObj),
    };
  },
  mounted() {
    this.docId = this.$route.params.id as string;
    this.record = [];
    this.init();

    (<any>window).vqd = this;
  },

  unmounted: async function () {
    await this.releaseDocLock({ doc_id: this.record.doc_id });
  },
  methods: {
    async init() {
      try {
        this.processing = true;

        await this.getDocumentById(this.docId);
        if (
          !this.record ||
          Object.keys(this.record).length === 0 ||
          this.record.success === false
        ) {
          return;
        }

        const response: any =
          await documentDetailApiService.getAdditionalAttributes(this.doctype);
        if (response.success) {
          this.prepareDefaultVaueObj(response);
        }

        this.makeModel();
        this.handleReadOnly();
        this.initPage();
      } catch (err: any) {
        logError(err);
        if (
          err != null &&
          typeof err == 'object' &&
          err.hasOwnProperty('message')
        ) {
          notify.error(err.message);
          return;
        }
        notify.error(
          'Error while displaying Page. Please reload again or contact admistrator',
        );
      } finally {
        this.processing = false;
      }
    },
    prepareDefaultVaueObj(reponse: any) {
      this.defalutAttributes['fields'] = {};
      this.defalutAttributes['table'] = {};

      if (reponse.field_attributes) {
        for (const [fieldName, properties] of Object.entries(
          reponse.field_attributes,
        )) {
          this.defalutAttributes['fields'][fieldName] = [];
          for (const [key, details] of Object.entries(properties as any)) {
            this.defalutAttributes['fields'][fieldName][key] = details as any;
          }
        }
      }

      if (reponse.table_attributes) {
        for (const [tableKey, table] of Object.entries(
          reponse.table_attributes,
        )) {
          for (const [fieldName, properties] of Object.entries(table as any)) {
            this.defalutAttributes['table'][fieldName] = [];
            for (const [key, details] of Object.entries(properties as any)) {
              this.defalutAttributes['table'][fieldName][key] = details as any;
            }
          }
          // only use first table
          break;
        }
      }
    },
    makeModel() {
      for (let field of this.record.fields) {
        if (field.formatted_value) {
          this.checkForDefaultValues(field);
          this.documentFields[field.name] = field;
        }
      }

      let groups = this.record.layout.groups;

      groups.forEach((group: any, index: any) => {
        group.rows.forEach((row: any, index: any) => {
          row.forEach((subRow: any, index: any) => {
            if (this.documentFields[subRow.field_name]) {
              this.documentFieldsConfig.push(subRow);
            }
          });
        });
      });
    },
    checkForDefaultValues(field: any) {
      if (field.formatted_value) {
        return;
      }

      if (
        !this.defalutAttributes['fields'][field.name] &&
        !this.defalutAttributes['fields'][field.name]['UI_DEFAULT_VALUE']
      ) {
        return;
      }

      const defalutvalue =
        this.defalutAttributes['fields'][field.name]['UI_DEFAULT_VALUE'];

      if (!defalutvalue) {
        return;
      }

      field.value = defalutvalue;
      field.formatted_value = defalutvalue;
      field.extraction_method = 'UD';
    },
    splitterChanged() {
      let screenWidth = window.innerWidth;
      let dynamicWidth = (screenWidth * (100 - this.imageFieldSplitter)) / 100;
      this.dynamicWidth = dynamicWidth;
    },
    openImageInSeparateWindow() {
      let route = this.$router.resolve({ path: '/po-image' });
      window.open(
        route.href,
        '_blank',
        'toolbar=yes,scrollbars=yes,resizable=yes,left=500,width=1000,height=1000',
      );
    },
    onZoomChange(val: number) {
      this.imageZoom = val;
    },
    currentPage() {
      return this.page;
    },
    scrollToPage(pageNum: any) {
      const num = parseInt(pageNum);
      if (!num || num < 1 || !this.record.images || num > this.record.images.length) {
        return;
      }
      this.page = num;
    },
    validatePageNumber() {
      if (!this.page || this.page < 1) {
        this.page = 1;
      }
      if (this.record.images && this.page > this.record.images.length) {
        this.page = this.record.images.length;
      }
      this.scrollToPage(this.page);
    },
    prevPage() {
      if (this.page <= 1) return;
      this.page--;
    },
    nextPage() {
      if (!this.record.images || this.page >= this.record.images.length) return;
      this.page++;
    },

    handleReadOnly() {
      if (this.record.status != CONSTANTS.ready_for_validation) {
        this.is_view_readonly = true;
        this.trigger_document_lock = false;
        this.error_message = this.$t('READ_ONLY_MSG');
        return;
      }

      this.trigger_document_lock = true;

      // check for access - pass the document to check permissions based on doc_type
      if (!Acl.canUpdate(this.record)) {
        this.is_view_readonly = true;
      }
    },

    initLineItems() {
      const event = new CustomEvent('init_line_items', { detail: this.record });
      document.dispatchEvent(event);
    },
    initPage() {
      if (!this.record || !this.record.fields) {
        return;
      }

      this.table_name =
        this.record.tables &&
        this.record.tables.length > 0 &&
        this.record.tables[0].hasOwnProperty('name')
          ? this.record.tables[0].name
          : '';

      this.setDataToCache();
      this.initLineItems();
    },

    toggleImageArea() {
      if (this.imageFieldSplitter >= 90) {
        this.imageFieldSplitter = 70;
      } else {
        this.imageFieldSplitter = 100;
      }
    },

    togglePoImage() {
      if (this.togglerIcon === 'chevron_left') {
        this.togglerIcon = 'chevron_right';
      } else {
        this.togglerIcon = 'chevron_left';
      }
      ($('#po-image-container') as HTMLElement).classList.toggle('hidden');
      ($('#po-container-parrent') as HTMLElement).classList.toggle(
        'po-container-parrent',
      );
      ($('#po-container-parrent') as HTMLElement).classList.toggle(
        'po-container-parrent-full-width',
      );
    },

    routeToBack() {
      try {
        if (history.state.back) {
          this.$router.back();
          return;
        }
        this.$router.push('/field_validation_v1/' + this.docId);
      } catch (err) {
        logError(err);
        this.$router.push('/field_validation_v1/' + this.docId);
      }
    },

    gotoTaskPendingList() {
      useTaskStore().prepareForDocPendingTasks(this.docId);
      this.$router.push('/tasks');
    },
    setTriggerDocumentLock(isLocked: boolean) {
      this.trigger_document_lock = isLocked;
    },
  },

  setup() {
    const doc_store = useDocumentStore();
    const { record, error, processing, doctype, bannerBg } =
      storeToRefs(doc_store);
    const { getDocumentById, saveDocument, removeCache, setDataToCache } =
      doc_store;
    const doc_lock_store = useDocLockStore();
    const { releaseDocLock } = doc_lock_store;

    const { current_sidebar, sidebarWidthClass, rightSectionClass, toggleSideBar } = useSidebarPanel();
    const { tokenQueryParam } = useImageAuth();

    let data: any = [];
    return {
      current_sidebar,
      sidebarWidthClass,
      rightSectionClass,
      toggleSideBar,
      tokenQueryParam,
      removeCache,
      saveDocument,
      setDataToCache,
      getDocumentById,
      releaseDocLock,
      record,
      doctype,
      bannerBg,
      processing,
      doc_fetch_error: ref(error),
      trigger_document_lock: ref(false),
      is_view_readonly: ref(false),
      documentFields: ref([] as dynamicObj),
      documentFieldsConfig: ref([] as any),
      togglerIcon: ref('chevron_right'),
      baseUrl: DOC2API_URL,
      table_name: ref(''),
    };
  },
});
</script>

