<!--vbase-->
<template>
  <div class="full-width q-pa-sm back-white" v-if="hasLineItems()">
    <f-btn
      :label="$t('add_line_row')"
      @click="addLineRow()"
      class="q-ma-xs float-right"
      v-if="!isReadOnly"
    />
  </div>

  <div class="full-width q-pa-sm back-white" :key="renderKey">
    <q-table
      v-if="hasLineItems()"
      :rows="tableRows"
      :columns="tableColumns"
      flat
      row-key="id"
      :no-data-label="$t('no_record_found')"
      :rows-per-page-options="[0]"
      :hide-header="false"
      id="line_item_table"
      ref="el"
      class="text-uppercase sticky-header transparent-header table_height resizable"
      style="table-layout: fixed !important; width: 100%"
    >
      <template v-slot:header="props">
        <q-tr :props="props">
          <q-th
            v-for="(col, index) in props.cols"
            :key="col.name"
            :props="props"
            class="table-column-header"
            :draggable="allowedColumnSorting(col)"
            :dropzone="allowedColumnSorting(col)"
            :data-index="index"
            direction="horizontal"
            @dragstart="onDragStart($event, tableColumns, index)"
            @drop.prevent="handleDrop($event, index)"
            @dragover.prevent="onDragOverWrapper($event, index, col.name)"
            @dragenter.prevent="onDragEnter"
            @dragleave.prevent="onDragLeave"
            :style="{
              cursor:
                getIsDragging && allowedColumnSorting(col) ? 'pointer' : 'move',
            }"
          >
            {{ col.label }}
            <q-icon
              v-if="col.error"
              :title="$t('in_valid_column_error')"
              name="priority_high"
              class="headerError"
            >
              <q-tooltip>
                {{ $t('in_valid_column_error') }}
              </q-tooltip>
            </q-icon>
          </q-th>
        </q-tr>
      </template>

      <template v-slot:body="props">
        <q-tr
          :props="props"
          :data-id="props.key"
          class="cursor-pointer"
          :class="{
            'alternative-row': props.rowIndex % 2 !== 0,
            'rejected-row': isRejectedRow(props.row?.SUPPLIER_ITEM_NUMBER),
          }"
          @click="onRowClick(props.row, props.rowIndex)"
        >
          <template v-for="col in props.cols" :key="col.name" :props="props">
            <q-td :data-id="props.key">
              <template v-if="col.label === ''">
                <template
                  v-if="record.tables[0].rows[props.rowIndex].is_user_defined"
                >
                  <q-icon size="sm" tabindex="0" class="cursor-pointer">
                    <Icon icon="mdi:account-edit" width="20" height="20" />
                    <q-tooltip>
                      {{ $t('custom_line') }}
                    </q-tooltip>
                  </q-icon>
                  <q-btn
                    flat
                    tabindex="0"
                    color="blue"
                    icon="close"
                    @click="
                      $event.preventDefault();
                      removeLineItem(props.row.id, props.rowIndex);
                    "
                  />
                </template>
                <template v-else>
                  <q-icon size="sm" tabindex="0" class="cursor-pointer">
                    <Icon icon="mdi:text-box-check" width="20" height="20" />
                    <q-tooltip>
                      {{ $t('extracted_line') }}
                    </q-tooltip>
                  </q-icon>
                </template>
              </template>
              <template v-else>
                {{ col.value }}
              </template>
            </q-td>
          </template>
        </q-tr>
      </template>
    </q-table>
    <q-markup-table style="height: '200px'" class="full-width" v-else>
      <thead>
        <tr v-if="lineItemsloading === false">
          <th>{{ $t('no_line_items_found') }}</th>
        </tr>
        <tr v-if="lineItemsloading === true">
          <th><q-spinner color="primary" size="3em" :thickness="10" /></th>
        </tr>
      </thead>
    </q-markup-table>
  </div>

  <template v-if="selectedRow && Object.entries(selectedRow).length > 0">
    <q-separator class="q-mt-md" />

    <div class="row back-white q-mt-md">
      <template v-for="(item, index) of sortedTableColumns" :key="index">
        <div
          :class="'col-sm-' + getColSpan(item.name)"
          class="q-pa-sm"
          v-if="item.name != 'status' && lineItemLayout[item.name]"
        >
          <div
            class="row"
            :class="getType(item.name) ? '' : ' input-text-28px'"
          >
            <div class="col-sm-12 col-md-12 col-lg-12">
              {{ formatLabel(item) }}
              <q-icon
                name="info"
                color="primary"
                v-if="getUiPreference(item.name, 'UI_DEFAULT_VALUE')"
              >
                <q-tooltip>{{ $t('field_has_default_value') }}</q-tooltip>
              </q-icon>
            </div>
            <div class="col-sm-12 col-md-12 col-lg-12">
              <q-input
                outlined
                dense
                v-model="selectedRow[item.name]"
                readonly
                v-if="lineItemLayout[item.name].column_type == 'DATE'"
                :disable="isReadOnly || getUiReadOnly(item.name)"
                class="p-b-0"
              >
                <template v-slot:append>
                  <q-icon
                    v-if="fieldErros[item.name]"
                    flat
                    dense
                    name="error"
                    size="22px"
                    color="red"
                  >
                    <q-tooltip
                      class="bg-red"
                      anchor="bottom left"
                      self="top left"
                    >
                      {{ fieldErros[item.name] }}
                    </q-tooltip>
                  </q-icon>
                  <q-icon name="event" class="cursor-pointer">
                    <q-popup-proxy
                      cover
                      transition-show="scale"
                      transition-hide="scale"
                    >
                      <q-date
                        v-model="selectedRow[item.name]"
                        :mask="getJsDateFormate()"
                        @update:model-value="
                          (val: any) => {
                            changeEvent(item.name, val);
                          }
                        "
                      >
                        <div class="row items-center justify-end">
                          <q-btn
                            v-close-popup
                            label="Close"
                            color="primary"
                            flat
                          />
                        </div>
                      </q-date>
                    </q-popup-proxy>
                  </q-icon>
                </template>

                <SelectAsDefault
                  :columnName="item.name"
                  :attributeValue="selectedRow[item.name]"
                  :tableKey="record.tables[0].name"
                  :doctype="doctype"
                />
              </q-input>
              <q-select
                outlined
                dense
                emit-value
                map-options
                v-model="selectedRow[item.name]"
                :use-input="item.name === 'DIMENSION5'"
                :clearable="item.name === 'DIMENSION5'"
                input-debounce="200"
                v-else-if="lovFields.hasOwnProperty(item.name)"
                :options="checkColumn(item.name)"
                @update:model-value="
                  (val: any) => {
                    dropDownChange(item.name, val);
                  }
                "
                :input-value="dimension5InputValueMap[item.name]"
                @input-value="(val: any) => onInputValueChange(item.name, val)"
                @blur="() => onBlurCheckRange(item.name)"
                :disable="isReadOnly || getUiReadOnly(item.name)"
              >
                <template v-slot:append>
                  <q-icon
                    v-if="fieldErros[item.name]"
                    flat
                    dense
                    name="error"
                    size="22px"
                    color="red"
                  >
                    <q-tooltip
                      class="bg-red"
                      anchor="bottom left"
                      self="top left"
                    >
                      {{ fieldErros[item.name] }}
                    </q-tooltip>
                  </q-icon>
                  <q-icon
                    v-if="lovFieldsList[getKey(item.name)]?.ranges?.length"
                    name="info"
                    class="cursor-pointer"
                    size="22px"
                    color="red"
                  >
                    <q-tooltip
                      class="bg-red"
                      anchor="bottom left"
                      self="top left"
                    >
                      <div style="white-space: pre-line">
                        {{
                          formatRangesTooltip(
                            lovFieldsList[getKey(item.name)]?.ranges,
                          )
                        }}
                      </div>
                    </q-tooltip>
                  </q-icon>
                </template>
                <SelectAsDefault
                  :columnName="item.name"
                  :attributeValue="selectedRow[item.name]"
                  :tableKey="record.tables[0].name"
                  :doctype="doctype"
                />
              </q-select>
               
              <q-input v-else outlined dense v-model="selectedRow[item.name]" :maxlength="getFieldLength(item.name)" :counter="getFieldLength(item.name) ? true : false"
                :type="getType(item.name) ? 'textarea' : 'input'" @update:model-value="(val: any) => { changeEvent(item.name,val); }" :disable="isReadOnly || getUiReadOnly(item.name)">
                <template v-slot:append >
                  <template v-if="lookup_loading_fields[selectedRow.id] && lookup_loading_fields[selectedRow.id].hasOwnProperty(item.name)">
                    <div v-if="lookup_loading_fields[selectedRow.id][item.name].lookup_loading">
                      <q-spinner-ios color="primary" size="0.86em" />
                    </div>

                    <q-icon v-if="lookup_loading_fields[selectedRow.id][item.name].lookup_found == true"
                      flat
                      dense
                      name="check_circle"
                      size="22px"
                      class="cursor-pointer text-light-green-8"
                      tabindex="0"
                    >
                      <q-tooltip>{{ $t('lookup_record_found') }}</q-tooltip>
                    </q-icon>

                    <q-icon
                      v-if="lookup_loading_fields[selectedRow.id][item.name].lookup_found == false"
                      flat
                      dense
                      name="warning"
                      size="22px"
                      class="cursor-pointer text-orange"
                      tabindex="0"
                    >
                      <q-tooltip>{{ interpolateForRow(selectedRow.id, item.name, $t('no_lookup_record_found_for_list')) }}</q-tooltip>
                    </q-icon>
                  </template>

                  <q-avatar class="cursor-pointer fuzzy-field" size="18px" v-if="lookup_configurations.has(item.name)">
                    <Icon icon="mdi:text-search" width="16" height="16" @click="$event.stopPropagation();$event.preventDefault(); masterDataSearchByField(selectedRow.id, lineDataObj[selectedRow.id]['columns'][item.name]);" />
                  </q-avatar>

                  <q-icon v-if="fieldErros[item.name]" flat dense name="error" size="22px" color="red" >
                    <q-tooltip class="bg-red" anchor="bottom left" self="top left">
                      {{ fieldErros[item.name] }}
                    </q-tooltip>
                  </q-icon>
                </template>

                <SelectAsDefault :columnName="item.name" :attributeValue="selectedRow[item.name]" :tableKey="record.tables[0].name" :doctype="doctype"/>

              </q-input>
            </div>
          </div>
        </div>
      </template>

      <div class="col-sm-12 col-md-12 col-lg-12 q-pt-md" v-if="!isReadOnly">
        <div class="row float-right">
          <f-btn
            :label="$t('cancel')"
            @click="selectedRow = {}"
            appearance="cancel"
            class="q-ma-xs"
            v-if="!isReadOnly"
          />
          <f-btn
            :label="$t('save')"
            @click="saveChanges(true, true, true)"
            class="q-ma-xs"
            v-if="!isReadOnly"
          />

          <q-btn-dropdown
            v-if="tableRows.length != selectedIndex + 1 && !isReadOnly"
            split
            unelevated
            color="primary"
            class="export-btn q-ma-xs"
            no-caps
            @click="saveAndNext()"
          >
            <template v-slot:label>
              <span class="export-label"> {{ $t('save_and_next') }}</span>
            </template>
            <q-list class="text-center">
              <q-item
                id="export_po_btn"
                clickable
                v-close-popup
                @click="saveAndNextCopyDefaults()"
                class="border-bottom-bdbdbd min-height-38"
              >
                <!-- <q-item-section avatar class="list-avatar">
              </q-item-section> -->
                <q-item-section>
                  <q-item-label>{{
                    $t('save_and_next_copy_defaults')
                  }}</q-item-label>
                </q-item-section>
              </q-item>
            </q-list>
          </q-btn-dropdown>
        </div>
      </div>
    </div>
  </template>
  <q-dialog
    v-model="showDialog"
    persistent
    transition-show="scale"
    transition-hide="scale"
  >
    <q-card class="note-card">
      <q-toolbar class="bg-primary text-white">
        <q-toolbar-title>
          <span class="text-weight-bold">{{
            $t('rejected_note') || 'Rejection Note'
          }}</span>
        </q-toolbar-title>

        <q-btn
          flat
          round
          dense
          icon="close"
          v-close-popup
          @click="showDialog = false"
        />
      </q-toolbar>

      <q-card-section>
        <q-input
          v-model="noteMessage"
          type="textarea"
          class="text-area-note"
          outlined
          readonly
          :label="'Note'"
        />
      </q-card-section>

      <q-card-actions align="right" class="q-pa-sm">
        <q-btn
          flat
          color="primary"
          :label="$t('cancel') || 'Cancel'"
          v-close-popup
          @click="showDialog = false"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <!-- FUZZY DIALOG STARTS -->

  <dialog-draggable
    v-model="fuzzyDialog"
    seamless
    full-width
    position="left"
    persistent
    @keydown.esc="closeMsDialog"
    :title="$t('validation')"
    @onHide="closeMsDialog"
    :isResizeAble="true"
    :draggable="isDraggle"
  >
    <masterDataLookup />
  </dialog-draggable>
  <Loader />
</template>

<script lang="ts">
// @ts-nocheck
type Range = { from: string; to: string };
type FixedValue = { label: string; value: string };
type NormalizedField = {
  fixedValues: FixedValue[];
  ranges: Range[];
};
import { notify } from 'src/components/notifications/notify';

import { storeToRefs } from 'pinia';
import { debounce, uid } from 'quasar';
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import Loader from 'src/components/Loader.vue';
import { type dynamicObj, $ } from 'src/pages/assets';
import { useResizeObserver } from '@vueuse/core';
import helperMixin from 'src/mixins/helperMixin';
import poActionsUtil from 'src/utils/poActionsUtil';
import { ApiExceptions } from 'src/exceptions/index';
import docTablesUtil from 'src/utils/docTablesUtil';
import { masterDataApiService } from 'src/services';
import dragDropColumn from 'src/mixins/dragDropColumn';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import { isUndefinedOrNull, isObject } from 'src/utils/general';
import { useDocumentStore, useSettingStore } from 'src/store/main';
import amountConversionHelper from 'src/utils/amountConversionHelper';
import {
  line_table_columns,
  AI_table_extraction_setting,
  quotes_detail_table_order,
  quote_fields_to_hide,
} from 'src/constants';
import SelectAsDefault from 'src/pages/QuoteDetails/Components/SelectAsDefault.vue';

import { objLen, isEmptyString } from 'src/utils/general';
import dialogDraggable from 'src/components/DialogDraggable.vue';
import masterDataLookup from 'src/pages/FieldValidation/masterDataLookup.vue';

import {
  useDocMasterDataLookUpStore,
  useLookupFunctionStore,
} from 'src/store/main';

let columnDataStatusMap = new Map();
// this Map conatins which column is completly empty and which column has atleast one record

export default defineComponent({
  el: '#app',
  mixins: [
    docTablesUtil,
    helperMixin,
    helperUtil,
    amountConversionHelper,
    poActionsUtil,
    displayFieldLabel,
    dateUtils,
    dragDropColumn,
  ],
  components: { Loader, masterDataLookup, dialogDraggable, SelectAsDefault },
  watch: {
    populate_row_to_view: {
      handler: function (newVal, oldVal) {
        if (newVal == false) {
          return;
        }
        this.populateMSDataFromPopup();
      },
    },
    'selectedRow.DIMENSION1': {
      handler: async function (newVal, oldVal) {
        //Make sure to trigger only if Accounting ID has been set
        if (newVal !== oldVal && oldVal == '' && newVal !== '') {
          //Get the configuration option
          const lookupConfig =
            this.record.tables[0].lookup_lov_configurations.find(
              (config: { column_name: string }) =>
                config.column_name === 'DIMENSION5',
            );
          const filter = JSON.stringify({
            [lookupConfig.fields[0].lookup_field]: newVal,
          });
          const key = 'DIMENSION5' + '_' + newVal;
          //Refetch the data and set in the list
          this.lovFieldsList[key] = await masterDataApiService.getLookupLov(
            String(lookupConfig.id),
            filter,
          );
        }
      },
    },
  },

  updated() {
    let setting = this.user_settings.LINE_ITEM_TABLE_SETTING;
    let height = 200;
    if (setting) {
      setting = JSON.parse(setting);
      height = setting.height as number;
    }
    const element = document.getElementById('line_item_table');

    if (element) {
      if (height < 200) {
        height = 200;
      }
      element.style.height = height + 'px';
    }
  },
  props: {
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    defaultValues: {
      type: Object,
      default: {} as any,
    },
  },
  data() {
    return {
      docId: '',
      renderKey: 0,
      validation_done: true,
      dropdownColumns: [] as any,
      lovFields: ref({} as dynamicObj),
      AI_table_extraction_setting,
      line_table_columns: line_table_columns,
      quotes_detail_table_order: quotes_detail_table_order,
      noteMessage: '',
      showDialog: false,
      dimension5InputValueMap: {} as dynamicObj,
      quote_fields_to_hide,
    };
  },

  mounted: function () {
    document.addEventListener('init_line_items', this.lineItemDataLoaded);
    document.addEventListener(
      'line_item_table-column-drop',
      this.savedSortedColumns,
    );
    this.init();
    this.initailizeDragColumnsById('line_item_table');
    (<any>window).vlqd = this;
  },
  unmounted: function () {
    document.removeEventListener('init_line_items', this.lineItemDataLoaded);
    document.removeEventListener(
      'line_item_table-column-drop',
      this.savedSortedColumns,
    );
  },
  methods: {
    init() {
      this.checkAITableSetting();

      this.debounceAutoTriggerFunc = debounce(
        this.triggerDependentFieldsWrapper.bind(this),
        1000, // Delay time in milliseconds
      );
    },
    onDragOverWrapper(event: any, index: any, name: string) {
      this.onDragOver(event, index);
    },
    allowedColumnSorting(column: any) {
      return column.name !== 'id' && column.name !== 'action_column';
    },
    formatRangesTooltip(ranges: any) {
      return (
        'Available ranges:\n' +
         
        ranges?.map((r: any) => `${r.from} → ${r.to}`).join('\n')
      );
    },

    isRejectedRow(supplierItemId: string): boolean {
      if (!supplierItemId) return false;

      const data = this.record?.quote_approval_data as Array<{
        supplier_item_id: string;
        approval_info: { approval_status: string };
      }>;
      const APPROVAL_STATUS_REJECTED = 'rejected';
      return (
        data?.some(
          (entry) =>
            entry.supplier_item_id === supplierItemId &&
            entry.approval_info?.approval_status === APPROVAL_STATUS_REJECTED,
        ) ?? false
      );
    },

    lineItemDataLoaded(e: any) {
      if (!e || !e.detail) {
        return;
      }
      this.lineItemsloading = false;
      // let data = e.detail;
      this.resetRows();
      // this.record = data;
      this.docId = this.record && this.record.doc_id ? this.record.doc_id : '';
      this.refactorApiData();
      this.triggerLineItemDataLoadedEvent();
      this.setupLookup();
    },

    triggerLineItemDataLoadedEvent() {
      const event = new CustomEvent('line_items_loaded', {});
      document.dispatchEvent(event);
    },

    savedSortedColumns() {
      const columnList: any = [];
      this.tableColumns.forEach((element: any, index: number) => {
        columnList[element.name] = element;
        if (columnList[element.name]) {
          columnList[element.name]['org_index'] = index;
        }
      });

      this.updatedLineColumns(this.tableColumns);
    },
    async updatedLineColumns(columns: any) {
      try {
        this.showLoading();
        let line_key = this.line_table_columns + '_' + this.doctype;
        await this.updateSetting(line_key, JSON.stringify(columns));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    resetRows() {
      this.tableRows = [];
      this.lineDataObj = {} as dynamicObj;
    },
    refactorApiData() {
      // DONT CHANGE THE ORDER OF FUNCTIONS CALLS
      this.is_ai_table = this.isAI_TableExit(this.record);
      this.setFormatOptions();
      this.table_name =
        this.record.tables &&
        this.record.tables.length > 0 &&
        this.record.tables[0].hasOwnProperty('name')
          ? this.record.tables[0].name
          : '';

      this.prepareTableLayoutObj();
      this.prepareTableColumn();
      this.prepareTableRowsAndRowObj();
      //
      // prepare line Item headers
      this.validateLineItemColumns();
    },
    setFormatOptions() {
      this.formatting_options = {};
      if (
        this.record.tables[0] &&
        this.record.tables[0].hasOwnProperty('formatting_options')
      ) {
        this.formatting_options = this.record.tables[0].formatting_options;
      }

      this.record.tables[0].formatting_options = this.formatting_options;

      if (
        this.formatting_options.hasOwnProperty('columns_to_hide') &&
        this.formatting_options.columns_to_hide !== null
      ) {
        this.columns_to_hide = Object.assign(
          [],
          this.formatting_options.columns_to_hide,
        );
      }
      if (
        this.formatting_options.hasOwnProperty('custom_columns_to_hide') &&
        this.formatting_options.custom_columns_to_hide !== null
      ) {
        this.custom_columns_to_hide = Object.assign(
          [],
          this.formatting_options.custom_columns_to_hide,
        );
      }

      if (
        !this.formatting_options.hasOwnProperty('column_origins') ||
        isUndefinedOrNull(this.formatting_options.column_origins) ||
        !isObject(this.formatting_options.column_origins)
      ) {
        this.record.tables[0].formatting_options.column_origins = {};
        this.formatting_options.column_origins = {};
      }
    },
    prepareTableLayoutObj() {
      // remove duplicate
      this.dropdownColumns = [];
      let duplicate_columns = {} as dynamicObj;
      this.lineItemLayout = {} as dynamicObj;

      if (
        !(
          this.record.tables &&
          this.record.tables.length > 0 &&
          this.record.tables[0].hasOwnProperty('layout')
        )
      ) {
        return;
      }
      Array.from(this.record.tables[0].layout).forEach((column: any) => {
        if (!duplicate_columns.hasOwnProperty(column.column_name)) {
          // prepare Coloum layout
          column['lbl_to_display'] = this.getLabelToDisplay(column);
          this.lineItemLayout[column.column_name] = column;
          if (column.is_hidden == false) {
            duplicate_columns[column.column_name] = true;
            // prepare Coloum Dropdown
            this.dropdownColumns.push({
              header: column.lbl_to_display,
              techName: column.column_name,
            });
          }
        }
      });
    },

    prepareTableRowsAndRowObj() {
      this.tableRows = [];
      this.lineDataObj = {} as dynamicObj;
      let lineDataTemp = {} as dynamicObj;

      // formate table rows data
      if (
        !this.record.tables ||
        this.record.tables.length == 0 ||
        !this.record.tables[0].hasOwnProperty('rows') ||
        this.record.tables[0].rows.length == 0
      ) {
        return;
      }

      Array.from(this.record.tables[0].rows).forEach((row: any) => {
        if (row.is_deleted === false) {
          let newRow: dynamicObj = {};
          // Clone 'Data' deeply
          lineDataTemp[row.id] = JSON.parse(JSON.stringify(row));

          // prepare row location list to get on indexes
          lineDataTemp[row.id].locations_list = [] as any;
          if (row.locations_list) {
            Array.from(row.locations_list).forEach((location: any) => {
              lineDataTemp[row.id].locations_list['page_' + location.page] =
                location;
            });
          }

          delete lineDataTemp[row.id].columns;
          lineDataTemp[row.id]['columns'] = [] as any;
          Array.from(row.columns).forEach((column: any) => {
            lineDataTemp[row.id].columns[column.name] = JSON.parse(
              JSON.stringify(column),
            );

            // prepare column location list to get on indexes
            lineDataTemp[row.id].columns[column.name].locations_list =
              [] as any;
            if (column.locations_list) {
              Array.from(column.locations_list).forEach((location: any) => {
                lineDataTemp[row.id].columns[column.name].locations_list[
                  'page_' + location.page
                ] = location;
              });
            }

            //prepare line item Table rows
            if (
              isUndefinedOrNull(column.formatted_value) ||
              column.formatted_value == ''
            ) {
              column.formatted_value = '';
              // set default Value
              const uiDefaultValue = this.getUiPreference(
                column.name,
                'UI_DEFAULT_VALUE',
              );
              if (uiDefaultValue) {
                column.value = uiDefaultValue;
                column.formatted_value = uiDefaultValue;
                column.extraction_method = 'UD';
              }
            }

            newRow[column.name] = column.formatted_value;
            this.prepareMapOfColumnHavingData(column);
          });
          // column for buttons
          this.addExtraColumnsInRow(lineDataTemp, newRow, row.id);
          newRow['id'] = row.id;
          newRow['show_charges'] = false;

          const is_additional_cost =
            row.hasOwnProperty('is_additional_cost') &&
            row.is_additional_cost === true;
          if (!is_additional_cost) {
            this.tableRows.push(newRow);
          }
        }
      });

      Object.assign(this.lineDataObj, lineDataTemp);
    },

    prepareMapOfColumnHavingData(column: any) {
      if (columnDataStatusMap.has(column.name)) {
        if (columnDataStatusMap.get(column.name) === false) {
          if (
            column.formatted_value &&
            column.formatted_value != null &&
            column.formatted_value != ''
          ) {
            columnDataStatusMap.set(column.name, true);
          }
        }
      } else {
        if (
          column.formatted_value &&
          column.formatted_value != null &&
          column.formatted_value != ''
        ) {
          columnDataStatusMap.set(column.name, true);
        } else {
          columnDataStatusMap.set(column.name, false);
        }
      }
    },

    addExtraColumnsInRow(lineDataTemp: any, newRow: any, rowId: string) {
      for (let colName of this.layoutExtraColumns) {
        let newColumObj = {
          name: colName,
          value: '',
          content: '',
          locations: [],
          locations_list: [],
          formatted_value: '',
          is_extra_column: true,
        };

        lineDataTemp[rowId].columns[colName] = newColumObj;
        columnDataStatusMap.set(colName, false);
        newRow[colName] = '';
      }
    },

    sortTableColumn() {
      this.tableColumns.sort((a: any, b: any) => {
        if (a.sortOrder < b.sortOrder) {
          return -1;
        }
        if (a.sortOrder > b.sortOrder) {
          return 1;
        }
        return 0;
      });
    },

    prepareTableColumn() {
      this.tableColumns = [];
      const is_empty_rows = this.record.tables[0].rows.length === 0;
      // empty Column for buttons
      this.tableColumns.push({
        name: 'status',
        field: 'status',
        align: 'left',
        label: '',
        is_mapped: true,
        org_index: '',
      });
      if (
        !(
          this.record.tables &&
          this.record.tables.length > 0 &&
          this.record.tables[0].hasOwnProperty('layout')
        )
      ) {
        return;
      }

      if (this.is_ai_table && !is_empty_rows) {
        this.AI_TableColumns();
      } else if (is_empty_rows) {
        this.layoutHeader();
      } else {
        this.normalTableColumns();
      }

      this.sortTableColumn();

      // set default value for column
      this.sortedTableColumns = this.sortColumnsByLayout(
        JSON.parse(JSON.stringify(this.tableColumns)),
      );
    },

    sortColumnsByLayout(inputArray: any[]) {
      const sortedArray: any[] = [];
      const remainingColumns: any[] = [];

      inputArray.forEach((column) => {
        const layoutItem: any = this.quotes_detail_table_order.find(
          (order: any) => order.name === column.column_name,
        );
        if (this.quote_fields_to_hide.includes(String(column.name))) {
          return;
        }
        if (layoutItem) {
          column.sortOrder = layoutItem.sortOrder;
          sortedArray.push(column);
        } else {
          remainingColumns.push(column);
        }
      });

      sortedArray.sort((a, b) => a.sortOrder - b.sortOrder);
      sortedArray.push(...remainingColumns);
       
      return sortedArray;
    },

    normalTableColumns() {
      const row = this.record.tables[0].rows[0];

      if (!row) {
        return;
      }
      let tempColumnArray: any = {};
      let tempLineItemLayout = JSON.parse(JSON.stringify(this.lineItemLayout));
      Array.from(row.columns).forEach((column: any) => {
        let allowed = this.isColumnHidden(row, column);
        if (allowed && column.name != 'id') {
          // Add only those column that are in the layout
          let label = column.name;
          let dataType = '';
          let sortOrder = 9999;

          if (this.lineItemLayout.hasOwnProperty(column.name)) {
            label = this.lineItemLayout[column.name].lbl_to_display;
            dataType = this.lineItemLayout[column.name].column_type;
            sortOrder = this.lineItemLayout[column.name].sort_order;
            delete tempLineItemLayout[column.name];
          }

          let org_index = '';
          if (column.org_index != null && column.org_index != undefined) {
            org_index = String(column.org_index);
          }

          let columnItem = {
            name: column.name,
            field: column.name,
            align: 'left',
            label: label,
            is_mapped: column.is_mapped ? column.is_mapped : false,
            org_index: org_index,
            col_origin: 'auto',
            dataType: dataType ? dataType.toLowerCase() : 'string',
            sortable: true,
            sortOrder: sortOrder,
          };

          columnItem.col_origin = this.getColumnOrigin(
            this.record.tables[0],
            column.name,
          );

          if (column.hasOwnProperty('org_index') && column.org_index != null) {
            this.tableColumns.push(columnItem);
          } else {
            tempColumnArray[column.name] = columnItem;
          }
        }
      });

      for (let [key, value] of Object.entries(tempColumnArray)) {
        this.tableColumns.push(Object.assign({}, value));
      }

      // at the end add extra column in the table that are in the layout
      for (let index in tempLineItemLayout) {
        const column = tempLineItemLayout[index];

        let allowed = !this.isCustomColumnHidden(column.name);
        if (!allowed) {
          delete tempLineItemLayout[column.name];
          continue;
        }

        const dataType = this.lineItemLayout[column.column_name].column_type;
        let columnItem = {
          name: column.column_name,
          field: column.column_name,
          align: 'left',
          label: column.lbl_to_display,
          is_mapped: column.is_mapped ? column.is_mapped : false,
          org_index: '',
          is_extra_column: true,
          col_origin: 'auto',
          dataType: dataType ? dataType.toLowerCase() : 'string',
          sortable: true,
        };

        columnItem.col_origin = this.getColumnOrigin(
          this.record.tables[0],
          column.column_name,
        );
        this.tableColumns.push(Object.assign({}, columnItem));
        this.layoutExtraColumns.push(column.column_name);
      }
    },

    getOrignalColumnName(column: any) {
      if (
        !column.hasOwnProperty('original_name') ||
        isUndefinedOrNull(column.original_name)
      ) {
        return '';
      }
      return String(column.original_name);
    },

    is_AI_ColumnVisible(column: any) {
      let visbile = true;

      let original_name = this.getOrignalColumnName(column);
      if (
        !original_name ||
        !this.formatting_options ||
        !this.formatting_options.hasOwnProperty('columns_to_hide') ||
        !this.formatting_options.columns_to_hide ||
        this.formatting_options.columns_to_hide.length == 0
      ) {
        return visbile;
      }

      if (
        this.formatting_options.columns_to_hide.includes(original_name) ||
        column.name == 'UUID'
      ) {
        visbile = false;
      }

      return visbile;
    },

    is_AI_isColumnHidden(row: any, column: any) {
      let original_name = '';
      if (column.original_name != null && column.original_name != undefined) {
        original_name = String(column.original_name);
      }

      let allowed = true;
      if (original_name !== '') {
        allowed = this.is_AI_ColumnVisible(column);
      }

      if (original_name === '') {
        allowed = !this.isCustomColumnHidden(column.name);
      }

      if (allowed && this.lineItemLayout[column.name]) {
        allowed = !this.lineItemLayout[column.name].is_hidden;
      }
      return allowed;
    },

    layoutHeader() {
      const layout = this.record.tables[0].layout;
      if (!layout || layout.length === 0) {
        return;
      }
      Array.from(layout).forEach((column: any) => {
        if (this.isCustomColumnHidden(column.column_name)) {
          return;
        }
        let label = column.lbl_to_display;
        let dataType = '';
        let isRequired = '';
        let alwaysVisible = '';
        let sortOrder = 9999;

        if (this.lineItemLayout.hasOwnProperty(column.column_name)) {
          label = this.lineItemLayout[column.column_name].lbl_to_display;
          dataType = this.lineItemLayout[column.column_name].column_type;
          isRequired = this.lineItemLayout[column.column_name].is_required;
          alwaysVisible =
            this.lineItemLayout[column.column_name].always_visible;
          sortOrder = this.lineItemLayout[column.column_name].sort_order;
        }

        let org_index = '';
        if (column.org_index != null && column.org_index != undefined) {
          org_index = String(column.org_index);
        }

        let columnItem = {
          name: column.column_name,
          field: column.column_name,
          align: 'left',
          label: label,
          is_mapped: column.is_mapped ? column.is_mapped : false,
          org_index: org_index !== '' ? org_index : '',
          dataType: dataType ? dataType.toLowerCase() : 'string',
          sortable: true,
          is_required: isRequired,
          always_visible: alwaysVisible,
          is_extra_column: column.hasOwnProperty('is_extra_column')
            ? column.is_extra_column
            : false,
          original_name: this.getOrignalColumnName(column),
          sortOrder: sortOrder,
        };
        if (column.hasOwnProperty('org_index') && column.org_index != null) {
          this.tableColumns.push(columnItem);
        } else {
          this.tableColumns.push(Object.assign({}, columnItem));
        }
      });
    },
    AI_TableColumns() {
      let added_columns = {} as dynamicObj;
      let tempColumnArray: any = [];

      Array.from(this.record.tables[0].rows).forEach((row: any) => {
        Array.from(row.columns).forEach((column: any) => {
          let allowed = this.is_AI_isColumnHidden(row, column);
          if (allowed && !added_columns.hasOwnProperty(column.name)) {
            added_columns[column.name] = true;
            let label = column.name;
            let dataType = '';
            let isRequired = '';
            let alwaysVisible = '';
            let sortOrder = 9999;

            if (this.lineItemLayout.hasOwnProperty(column.name)) {
              label = this.lineItemLayout[column.name].lbl_to_display;
              dataType = this.lineItemLayout[column.name].column_type;
              isRequired = this.lineItemLayout[column.name].is_required;
              alwaysVisible = this.lineItemLayout[column.name].always_visible;
              sortOrder = this.lineItemLayout[column.name].sort_order;
            }

            let org_index = '';
            if (column.org_index != null && column.org_index != undefined) {
              org_index = String(column.org_index);
            }

            let columnItem = {
              name: column.name,
              field: column.name,
              align: 'left',
              label: label,
              is_mapped: column.is_mapped ? column.is_mapped : false,
              org_index: org_index !== '' ? org_index : '',
              dataType: dataType ? dataType.toLowerCase() : 'string',
              sortable: true,
              is_required: isRequired,
              always_visible: alwaysVisible,
              is_extra_column: column.hasOwnProperty('is_extra_column')
                ? column.is_extra_column
                : false,
              original_name: this.getOrignalColumnName(column),
              sortOrder: sortOrder,
            };

            const is_non_mapped_allowed =
              columnItem.is_mapped ||
              (!this.remove_unmapped_columns && !columnItem.is_mapped);

            if (
              column.hasOwnProperty('org_index') &&
              column.org_index != null &&
              is_non_mapped_allowed
            ) {
              this.tableColumns.push(columnItem);
            } else {
              tempColumnArray[column.name] = columnItem;
            }
          }
        });
      });

      for (let [key, value] of Object.entries(tempColumnArray)) {
        const column = value as dynamicObj;
        if (
          (column.hasOwnProperty('is_extra_column') &&
            column.is_extra_column === true) ||
          column.always_visible ||
          column.is_required
        ) {
          this.tableColumns.push(column);
        }
      }
    },

    isCustomColumnHidden(column_name: string) {
      let hidden = false;
      if (
        !this.custom_columns_to_hide ||
        this.custom_columns_to_hide.length == 0
      ) {
        return hidden;
      }

      for (const column of this.custom_columns_to_hide) {
        if (column === column_name) {
          hidden = true;
          break;
        }
      }

      return hidden;
    },

    isColumnHidden(row: any, column: any) {
      let org_index = '';
      if (column.org_index != null && column.org_index != undefined) {
        org_index = String(column.org_index);
      }

      let allowed = true;
      if (org_index !== '') {
        allowed = this.isColumnVisible(org_index, column);
      }

      if (allowed && this.lineItemLayout[column.name]) {
        allowed = !this.lineItemLayout[column.name].is_hidden;
      }
      return allowed;
    },

    isColumnVisible(index: string, column: any) {
      if (this.is_ai_table) {
        return this.is_AI_ColumnVisible(column);
      }

      let visbile = true;
      if (
        !index ||
        !this.formatting_options ||
        !this.formatting_options.hasOwnProperty('columns_to_hide') ||
        !this.formatting_options.columns_to_hide ||
        this.formatting_options.columns_to_hide.length == 0
      ) {
        return visbile;
      }

      if (
        this.formatting_options.columns_to_hide.includes(index) ||
        column.name == 'UUID'
      ) {
        visbile = false;
      }

      return visbile;
    },

    validateLineItemColumns() {
      let hasError = false;

      if (this.tableColumns === undefined) {
        return;
      }

      for (const column of this.tableColumns) {
        let isValid = this.isColumnNameValid(column);
        if (!isValid) {
          column.error = true;
          hasError = true;
          continue;
        }
      }

      let newValidation = !hasError;

      if (this.validation_done === newValidation) {
        return;
      }

      this.validation_done = newValidation;
    },
    isColumnNameValid(header: any) {
      let isValid = false;

      for (const column of this.dropdownColumns) {
        if (
          header.name === column.techName ||
          header.name == 'status' ||
          header.name == 'action_column'
        ) {
          isValid = true;
          break;
        }
      }

      return isValid;
    },
    hasOriginalIndex(index: any, item: any) {
      let hasIndex = false;
      if (index !== '') {
        hasIndex = true;
      }
      return hasIndex;
    },

    hasLineItems() {
      // Ensure layout exists
      if (this.lineItemLayout && Object.keys(this.lineItemLayout).length > 0) {
        return true;
      }

      // If rows exist and are not empty
      if (Array.isArray(this.tableRows) && this.tableRows.length > 0) {
        return true;
      }

      return false;
    },

    goTolineItemsPage() {
      this.removeCache();
      if (this.is_ai_table) {
        this.$router.push('/field_validation_v1/' + this.record.doc_id);
        return;
      }
      this.$router.push('/tbl_ext_v3/' + this.record.doc_id);
    },
    goToDashboard() {
      this.$router.push('/dashboard');
    },

    checkAITableSetting() {
      this.ai_table_setting_flag = false;
      if (this.user_settings[this.AI_table_extraction_setting]) {
        this.ai_table_setting_flag =
          this.user_settings[this.AI_table_extraction_setting];
      }
    },
    async onRowClick(row: any, index: number) {
      this.selectedRow = JSON.parse(JSON.stringify(row));
      this.selectedIndex = index;
      // load default dropdowns
      await this.triggerlookupLovs('', true, '', false);

      // load dropdowns who already have data
      await this.triggerlookupLovsHavingData();
      const supplierItemId = this.selectedRow?.SUPPLIER_ITEM_NUMBER; // Or row[column] if needed
      if (!supplierItemId) return;
      const approvalData = this.record?.quote_approval_data.find(
        (entry: any) =>
          entry.supplier_item_id.trim().toUpperCase() ===
          supplierItemId.trim().toUpperCase(),
      );
      const APPROVAL_STATUS_REJECTED = 'rejected';
      if (
        approvalData &&
        approvalData.approval_info?.approval_status === APPROVAL_STATUS_REJECTED
      ) {
        const note = approvalData.approval_info?.notes;
        if (note) {
          this.noteMessage = note;
          this.showDialog = true;
        }
      }
    },
    async saveAndNextCopyDefaults() {
      const oldRow = JSON.parse(JSON.stringify(this.selectedRow));
      await this.saveAndNext();
      for (let [key, value] of Object.entries(oldRow)) {
        if (this.getUiPreference(key, 'UI_DEFAULT_VALUE')) {
          this.selectedRow[key] = value;
        }
      }
    },
    async saveAndNext() {
      let isValid = await this.saveChanges(true, true, false);
      if (!isValid) {
        return;
      }
      this.selectedIndex++;

      const row = this.tableRows[this.selectedIndex];
      this.onRowClick(row, this.selectedIndex);
    },
    async saveChanges(
      showLoading: boolean,
      validate: boolean,
      clearObjects: boolean,
    ) {
      let isValid = false;

      if (this.isReadOnly) {
        return isValid;
      }

      if (validate && !this.validateData()) {
        return isValid;
      }
      try {
        if (showLoading) {
          this.showLoading();
        }

        this.tableRows[this.selectedIndex] = this.selectedRow;
        this.updateJsonForLineItems();
        const response = await this.saveDocument(this.docId);
        // reload table
        this.refactorApiData();
        this.removeCache();
        if (response.success === false) {
          throw response;
        }

        if (response.data.tables[0].messages) {
          isValid = this.getErros(response.data.tables[0].messages);

          if (!isValid) {
            clearObjects = false;
            return isValid;
          }
        }

        this.$forceUpdate();
        notify.success(this.$t('MSG_SAVE'));
        isValid = true;
      } catch (err) {
        isValid = false;
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        return;
      } finally {
        this.hideLoading();
        if (clearObjects) {
          this.selectedRow = {};
          this.selectedIndex = null;
        } else {
          // updated the object
          this.selectedRow = this.tableRows[this.selectedIndex];
        }
      }

      return isValid;
    },
    getErros(messages: any) {
      let errors = [] as any;
      for (const data of messages) {
        if (data.row_index == this.selectedIndex) {
          let message = data.message;
          if (data.hasOwnProperty('col_name')) {
            let label = this.$t(data.col_name);

            if (this.lineItemLayout.hasOwnProperty(data.col_name)) {
              label = this.lineItemLayout[data.col_name].lbl_to_display;
            }

            message = label + ': ' + message;
          }
          errors.push(message);
        }
      }

      let isValid = errors.length == 0;
      if (!isValid) {
        notify.error(errors.join('<br> '));
      }

      return isValid;
    },
    updateJsonForLineItems() {
      Array.from(this.record.tables[0].rows).forEach(
        (row: any, rowIndex: any) => {
          if (this.selectedRow.id === row.id) {
            Array.from(row.columns).forEach((column: any, columnIndex: any) => {
              this.record.tables[0].rows[rowIndex].columns[columnIndex].value =
                this.selectedRow[column.name];
              this.record.tables[0].rows[rowIndex].columns[
                columnIndex
              ].content = this.selectedRow[column.name];
              this.record.tables[0].rows[rowIndex].columns[
                columnIndex
              ].formatted_value = this.selectedRow[column.name];
              this.record.tables[0].rows[rowIndex].columns[
                columnIndex
              ].original_content = this.selectedRow[column.name];
            });
          }
        },
      );
    },
    validateData() {
      let isValid = true;

      for (let [key, value] of Object.entries(this.selectedRow)) {
        if (
          this.lineItemLayout[key] &&
          this.lineItemLayout[key].is_required &&
          !value
        ) {
          isValid = false;
          this.fieldErros[key] = this.$t('field_required');
          continue;
        }

        const count = this.getFieldLength(key);
        if (count && String(value).length > count) {
          this.selectedRow[key] = String(value).substring(0, count);
        }
      }

      return isValid;
    },

    getUiPreference(fieldName: string, uiPreferenceKey: string): any {
      if (
        this.defaultValues &&
        this.defaultValues.table &&
        this.defaultValues.table[fieldName] &&
        this.defaultValues.table[fieldName][uiPreferenceKey]
      ) {
        return this.defaultValues.table[fieldName][uiPreferenceKey];
      }

      return null;
    },
    getColSpan(colName: string) {
      const uiColSpan = this.getUiPreference(colName, 'UI_COL_SPAN');
      let colSpan = 3;
      if (uiColSpan) {
        colSpan = +uiColSpan * colSpan;
        if (colSpan > 12 || colSpan < 1) {
          colSpan = 3;
        }
      }
      return colSpan;
    },
    getUiReadOnly(colName: string) {
      const data = this.getUiPreference(colName, 'UI_READ_ONLY') as boolean;

      return data ? Boolean(data) : false;
    },
    getType(colName: string) {
      return this.getUiPreference(colName, 'UI_TEXT_AREA') as boolean;
    },
    getUppercaseType(colName: string) {
      return this.getUiPreference(colName, 'UI_TO_UPPER_CASE') as boolean;
    },
    formatLabel(item: any): string {
      return this.getUppercaseType(item.name)
        ? item.label.toUpperCase()
        : item.label;
    },
    async addLineRow() {
      const is_empty_rows = this.record.tables[0].rows.length === 0;

      let row: any;

      if (is_empty_rows) {
        // Build row from layout
        row = {
          id: uid(),
          coords: [],
          is_header_row: false,
          is_user_defined: true,
          is_deleted: false,
          columns: [] as any,
        };

        // Loop over layout columns
        for (let layoutCol of this.record.tables[0].layout) {
          const name = layoutCol.column_name || layoutCol.name;
          let value = '';

          if (name === 'POSITION') {
            value = '1';
          }

          const uiDefaultValue = this.getUiPreference(name, 'UI_DEFAULT_VALUE');
          if (uiDefaultValue) {
            value = uiDefaultValue;
          }

          row.columns.push({
            name,
            value,
            content: value,
            formatted_value: value,
            original_content: value,
            org_index: 0,
            extraction_method: 'UD',
            is_valid: true,
            is_mapped: true,
            is_validated: false,
            original_name: name,
          });
        }
      } else {
        // Clone last row
        const lastIndex = this.record.tables[0].rows.length - 1;
        row = JSON.parse(JSON.stringify(this.record.tables[0].rows[lastIndex]));
        row.id = uid();
        row.coords = [];
        row.is_header_row = false;
        row.is_user_defined = true;

        for (let column of row.columns) {
          let value = '';

          if (column.name === 'POSITION') {
            value = (Number(column.formatted_value) + 1).toString();
          }

          const uiDefaultValue = this.getUiPreference(
            column.name,
            'UI_DEFAULT_VALUE',
          );
          if (uiDefaultValue) {
            value = uiDefaultValue;
          }

          column.value = value;
          column.content = value;
          column.formatted_value = value;
          column.original_content = value;
          column.extraction_method = 'UD';
          column.org_index = column.org_index ? column.org_index + 1 : 0;
        }
      }

      // Push the new row
      this.record.tables[0].rows.push(row);
      this.prepareTableRowsAndRowObj();

      // Get the latest index from raw rows (not this.tableRows)
      const newIndex = this.record.tables[0].rows.length - 1;
      this.selectedIndex = newIndex;
      // Get correct row from original or transformed data
      const selectedRow =
        this.tableRows[newIndex] || this.record.tables[0].rows[newIndex];
      if (selectedRow) {
        await this.onRowClick(selectedRow, newIndex);
      }

      // ✅ Copy default values into selectedRow if needed
      const oldRow = this.tableRows[this.selectedIndex - 1];
      if (oldRow) {
        for (let [key, value] of Object.entries(oldRow)) {
          if (this.getUiPreference(key, 'UI_DEFAULT_VALUE')) {
            this.selectedRow[key] = value;
          }
        }
      }
    },

    // ============================================================================
    async dropDownChange(colName: string, value: string) {
      try {
        this.showLoading();
        this.updateTableValues(colName, value);
        await this.triggerlookupLovs(colName, false, value, true);
        if (value && this.fieldErros[colName]) {
          delete this.fieldErros[colName];
        }
      } catch (e) {
        logError(e);
      } finally {
        this.hideLoading();
      }
    },
    changeEvent(colName: string, value: string) {
      if (this.lineItemLayout[colName].column_type == 'DATE') {
        value = this.formatDateAccordingToPreference(value, true);
        this.selectedRow[colName] = value;
      }
      this.updateTableValues(colName, value);

      const config = this.autoTriggerLookups[colName];
      if (config) {
        this.autoTriggedFields = [];
        this.debounceAutoTriggerFunc(config, colName, false);
      }
      if (value && this.fieldErros[colName]) {
        delete this.fieldErros[colName];
      }
    },
    updateTableValues(field_name: string, formatted_value: any) {
      this.lineDataObj[this.selectedRow.id]['columns'][field_name].value =
        formatted_value;
      this.lineDataObj[this.selectedRow.id]['columns'][field_name].content =
        formatted_value;
      this.lineDataObj[this.selectedRow.id]['columns'][
        field_name
      ].formatted_value = formatted_value;

      this.selectedRow[field_name] = formatted_value;
    },
    async triggerlookupLovsHavingData() {
      const lovConfigurations = this.record.tables[0].lookup_lov_configurations;
      if (!lovConfigurations) {
        return;
      }
      for (const [index, value] of Object.entries(this.selectedRow)) {
        if (this.lovFields.hasOwnProperty(index)) {
          let columnName = this.lovFields[index].fields[0].column_name;

          if (columnName && this.selectedRow[columnName]) {
            await this.triggerlookupLovs(
              columnName,
              false,
              this.selectedRow[columnName],
              false,
            );
          }
        }
      }
    },
    async triggerlookupLovs(
      columName: string,
      triggerDefaultLovs: boolean,
      selectedValue: string,
      resetChild: boolean,
    ) {
      const lovConfigurations = this.record.tables[0].lookup_lov_configurations;
      if (!lovConfigurations) {
        return;
      }

      mainLoop: for (let config of lovConfigurations) {
        if (!config.fields || config.fields.length == 0) {
          continue;
        }

        if (!this.lovFieldsList[config.column_name]) {
          this.lovFields[config.column_name] = config;
          this.lovFieldsList[config.column_name] = [];
        }

        for (let field of config.fields) {
          if (triggerDefaultLovs) {
            if (field.column_name == null) {
              let filter = null;
              if (field.lookup_field) {
                filter = JSON.stringify({
                  [field.lookup_field]: [field.filter_value],
                });
              }

              this.lovFieldsList[config.column_name] =
                await masterDataApiService.getLookupLov(config.id, filter);
            }
          } else if (columName == field.column_name) {
            const filter = { [field['lookup_field']]: selectedValue };
            const key = config.column_name + '_' + selectedValue;
            this.lovFieldsList[key] = await masterDataApiService.getLookupLov(
              config.id,
              JSON.stringify(filter),
            );
            if (resetChild) {
              this.selectedRow[config.column_name] = '';
            }

            break mainLoop;
          }
        }
      }
    },
    getKey(columnName: string) {
      let key = columnName;
      let parentColumnName = this.lovFields[columnName].fields[0].column_name;

      if (parentColumnName && this.selectedRow[parentColumnName]) {
        key = columnName + '_' + this.selectedRow[parentColumnName];
      }
      return key;
    },

    checkColumn(column: any) {
      const key = this.getKey(column);
      const field = this.lovFieldsList[key];

      if (column !== 'DIMENSION5') {
        return field || [];
      }
      if (field?.fixedValues) {
        return field.fixedValues;
      }
      if (Array.isArray(field)) {
        const normalized: Record<string, any> = this.normalizeLovFieldsList({
          [key]: field,
        });
        this.lovFieldsList[key] = normalized[key];
        return normalized.fixedValues || [];
      }
      return [];
    },

    normalizeLovFieldsList(
      lovFieldsList: Record<string, any[]>,
    ): Record<string, NormalizedField> {
      const result: Record<string, NormalizedField> = {};

      Object.keys(lovFieldsList).forEach((fieldKey: string) => {
        const rawList = lovFieldsList[fieldKey];
        const fixedValuesSet = new Set<string>();
        const ranges: Range[] = [];

        rawList.forEach((item: any) => {
          const from = item.from_accounting_identity_value?.trim();
          const to = item.to_accounting_identity_value?.trim();

          if (from && to) {
            if (from === to) {
              fixedValuesSet.add(from);
            } else {
              ranges.push({ from, to });
            }
          }
        });

        const fixedValues: FixedValue[] = Array.from(fixedValuesSet)
          .sort()
          .map((val: any) => ({ label: val, value: val }));

        result[fieldKey] = {
          fixedValues,
          ranges,
        };
      });

      return result;
    },

    onInputValueChange(columnName: string, val: string) {
      // Live tracking input
      this.dimension5InputValueMap[columnName] = val;
    },

    onBlurCheckRange(columnName: string) {
      const inputValue = this.dimension5InputValueMap[columnName]?.trim();
      const key = this.getKey(columnName);
      const { fixedValues, ranges } = this.lovFieldsList[key] || {
        fixedValues: [],
        ranges: [],
      };
      if (!inputValue) return;

      const matchFixed = fixedValues?.some(
        (opt: any) => opt.value === inputValue,
      );
      const matchRange = ranges?.some((range: { from: any; to: any }) => {
        return inputValue >= range.from && inputValue <= range.to;
      });

      if (matchFixed || matchRange) {
        this.selectedRow[columnName] = inputValue;
      } else {
        this.fieldErros[columnName] = this.$t('invalid_range_error');
      }
    },

    getFieldLength(field_name: string): any {
      return this.getUiPreference(field_name, 'UI_MAX_LENGTH');
    },
    removeLineItem(lineId: string, rowIndex: number) {
      let selectedRow = rowIndex;
      for (const [index, row] of Object.entries(this.record.tables[0].rows)) {
        if ((row as any).id === lineId) {
          selectedRow = Number(index);
          break;
        }
      }

      this.record.tables[0].rows.splice(selectedRow, 1);
      this.tableRows.splice(rowIndex, 1);

      this.selectedRow = {};
      this.selectedIndex = null;
    },

    // =========================================
    masterDataSearchByField(rowKey: string, fieldModel: any) {
      try {
        const field_name = fieldModel.name;
        const config = this.lookup_configurations.get(field_name);

        if (!config) {
          logError('field vardef is missing for master lookup', field_name);
          return;
        }

        const id = uid();
        const existingFilter = Object.values(this.ms_advance_filters).find( filter => filter.field_name === fieldModel.name );
        if(!existingFilter){
          this.ms_advance_filters[id] = {
            fuzzy_field: config.lookup_field.toLowerCase(),
            search_text: fieldModel.formatted_value,
            field_name,
            primary: true
          }

          this.master_lookup_type = config.lookup_dataset_name;

          // this.ms_view_model = this.formBuilderConfigModel
          this.master_data_fields_map = new Map();
          this.master_data_fields_map.set(this.master_lookup_type, config);
          this.master_data_popup_width = this.calculateWidthForMSPopuup();

          // primary fields
          if (config.parent_field_id && config.parent_field_id != '') {
            let parent_field = null;
            for (const [index, field] of config.fields.entries()) {
              if (config.parent_field_id == field.field_id) {
                parent_field = field;
                break;
              }
            }

            if (parent_field) {
              const id = uid();
              this.ms_advance_filters[id] = {
                fuzzy_field: parent_field.lookup_field.toLowerCase(),
                search_text: this.lineDataObj[rowKey]['columns'][parent_field.field_name].formatted_value,
                field_name: parent_field.field_name,
                primary: false
              }
            }

          }
        }

        this.fuzzyDialog = true;
      } catch (error) {
        logError(error);
      }
    },

    calculateWidthForMSPopuup() {
      let default_width = '700';
      const main_el = document.querySelector(
        '.field_validation',
      ) as HTMLElement;
      if (!main_el) {
        return default_width;
      }

      const fields_area_el = document.querySelector(
        '#field_scrolle',
      ) as HTMLElement;
      if (!fields_area_el) {
        return default_width;
      }

      const calculated_width = fields_area_el.offsetWidth;
      if (calculated_width <= 0) {
        return default_width;
      }
      return String(calculated_width);
    },
    setupLookup() {
      try {
        this.lookup_configurations = new Map();
        if (!this.record.tables[0].lookup_configurations) {
          return;
        }
        for (const [
          index,
          item,
        ] of this.record.tables[0].lookup_configurations.entries()) {
          if (!item.hasOwnProperty('fields') || !Array.isArray(item.fields)) {
            continue;
          }
          for (const [index, field] of item.fields.entries()) {
            if (field.auto_trigger) {
              this.autoTriggerLookups[field.column_name] = item;
            }

            if (!field.is_searchable) {
              continue;
            }

            this.lookup_configurations.set(
              field.column_name,
              Object.assign(JSON.parse(JSON.stringify(field)), {
                lookup_dataset_name: item.lookup_dataset_name,
                fields: JSON.parse(JSON.stringify(item.fields)),
              }),
            );
          }
        }
      } catch (e) {
        logError(e);
      }
    },
    populateMSDataFromPopup() {
      this.changed_fields = [];
      this.groups_to_update = [];

      let config = this.master_data_fields_map.get(this.master_lookup_type);

      this.populateMasterData(config, this.master_data_row);
      this.autoTriggedFields = [];
      this.triggerDependentFields(config, config.column_name, true);
    },
    async triggerDependentFieldsWrapper(
      config: any,
      colName: string,
      skipCurrentColumn: boolean,
    ) {
      await this.triggerDependentFields(config, colName, skipCurrentColumn);
    },
    async triggerDependentFields(
      config: any,
      colName: string,
      skipCurrentColumn: boolean,
    ) {
      if (
        !this.selectedRow[colName] ||
        this.autoTriggedFields.includes(colName.toLowerCase())
      ) {
        return;
      }

      for (let field of config.fields) {
        // this check is needed as fields can be in other groups and may not be auto trigger in each group
        const config = this.autoTriggerLookups[field.column_name];
        if (!config) {
          continue;
        }

        this.autoTriggedFields.push(colName.toLowerCase());
        // because colName is already auto triggered will be skiped in case when selected from popup
        if (
          skipCurrentColumn &&
          field.column_name.toLowerCase() == colName.toLowerCase()
        ) {
          continue;
        }

        await this.triggerLookup(field.column_name, config);
        this.triggerDependentFields(config, field.column_name, true);
      }
    },
    async triggerLookup(colName: string, config: any) {
      if (isUndefinedOrNull(colName) || isEmptyString(colName)) {
        return;
      }

      const master_lookup_type = config.lookup_dataset_name;

      if(!master_lookup_type) {
        return;
      }

      const fieldConfig = this.getFieldFromConfig(config, colName);

      const advance_filters = {} as dynamicObj;
      const id = uid();
      
      const rowId = this.selectedRow.id;
      if (!this.lookup_loading_fields[rowId]) {
        this.lookup_loading_fields[rowId] = {} as dynamicObj;
      }
      this.lookup_loading_fields[rowId][colName] = {} as dynamicObj;
      this.lookup_loading_fields[rowId][colName].lookup_loading = true;

      advance_filters[id] = {
        'field': {'field': fieldConfig.lookup_field},
        'operator': this.getOperator(fieldConfig),
        'search_text': this.lineDataObj[this.selectedRow.id]['columns'][colName].formatted_value,
      }

      let resp: any = await this.autoTriggerSearchByField(
        advance_filters,
        master_lookup_type
      )
      // no record or many record found it will be null
      if (resp != null) {
        const master_data_row = JSON.stringify(resp.data[0]);
        this.populateMasterData(config, master_data_row);
        this.lookup_loading_fields[rowId][colName].lookup_found = true;
      } else {
        this.lookup_loading_fields[rowId][colName].lookup_found = false;
        this.lookup_loading_fields[rowId][colName].lookup_found_name = master_lookup_type;
      }
      this.lookup_loading_fields[rowId][colName].lookup_loading = false;
    },
    getFieldFromConfig(config: any, fieldName: string): any {
      for (const [index, field] of config.fields.entries()) {
        if (field.column_name == fieldName) {
          return field;
        }
      }
    },
    getOperator(fieldConfig: any) {
      return fieldConfig.search_operator
        ? String(fieldConfig.search_operator)
        : 'contains';
    },
    // handleLookupFieldStatus (field_name: string, enable: boolean, set_lookup_status = true) {
    //   if (!this.lineDataObj[this.selectedRow.id]['columns'].hasOwnProperty(field_name)) {
    //     return;
    //   }

    //   if (!this.lookup_loading_fields.hasOwnProperty(field_name)) {
    //     this.lookup_loading_fields[field_name] = {} as dynamicObj;
    //   }
    //   this.lookup_loading_fields[field_name].lookup_loading = enable;
    //   if (set_lookup_status) {
    //     this.lookup_loading_fields[field_name].lookup_found = null;
    //     this.lookup_loading_fields[field_name].lookup_found_name = null;
    //   }
    // },
    interpolateForRow(rowId: string, field_name: string, value: string) {
      const re = /%name/gi;
      const entry = this.lookup_loading_fields[rowId]?.[field_name];
      if (!entry || !entry.lookup_found_name) {
        return value;
      }
      const str = entry.lookup_found_name;
      return value.replace(re, str);
    },

    closeMsDialog() {
      this.fuzzyDialog = false;
      this.ms_advance_filters = {};
    },

    populateMasterData(config: dynamicObj, data: string) {
      try {
        this.closeMsDialog();
        this.showLoading();
        // General Response-Data for all the respective Fields
        let jsonResponse = JSON.parse(data);
        const values = [];
        const lookup_fields = config.fields;

        for (let [index, field] of lookup_fields.entries()) {
          const field_name = field.column_name;
          const lookup_field = field.lookup_field.toLowerCase();
          if (
            !this.lineDataObj[this.selectedRow.id]['columns'].hasOwnProperty(
              field_name,
            )
          ) {
            continue;
          }

          if (
            jsonResponse.hasOwnProperty(lookup_field) == false ||
            jsonResponse[lookup_field] == null
          ) {
            continue;
          }

          let formatted_value = jsonResponse[lookup_field];

          // if lookup_field has name with name_formatted_value then it will be used as formatted value
          if (jsonResponse.hasOwnProperty(lookup_field + '_formatted_value')) {
            formatted_value = jsonResponse[lookup_field + '_formatted_value'];
          }

          this.updateTableValues(field_name, formatted_value);

          const rowId = this.selectedRow.id;
          if (!this.lookup_loading_fields[rowId]) {
            this.lookup_loading_fields[rowId] = {} as dynamicObj;
          }
          if(!this.lookup_loading_fields[rowId][field_name]) {
            this.lookup_loading_fields[rowId][field_name] = {} as dynamicObj;
            this.lookup_loading_fields[rowId][field_name].lookup_found = true;
          }
        }

        this.resetMasterDataStore();
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
  setup() {
    const el = ref(null)
    let data : any = [];
    let model =  {} as  {[k: string]: any};
    let lastRect: DOMRectReadOnly | null = null;

    const doc_store = useDocumentStore();
    const { record, doctype, remove_unmapped_columns } = storeToRefs(doc_store);
    const { removeCache, isAI_TableExit, saveDocument } = doc_store;

    function sizeChanged(prev: DOMRectReadOnly | null, curr: DOMRectReadOnly, tol = 0) {
      if (!prev) return true;
      const dh = Math.abs(prev.height - curr.height);
      const dw = Math.abs(prev.width  - curr.width);
      return dh > tol || dw > tol;          
    }

    useResizeObserver(
      el,
      debounce((entries) => {
        const entry = entries[0];
        const { width, height } = entry.contentRect;
        if (width < 20 || height < 20) return;
        if (!sizeChanged(lastRect, entry.contentRect, 2)) return;
        lastRect = entry.contentRect;
        setUserPreferences('LINE_ITEM_TABLE_SETTING', JSON.stringify({ width, height }));
      }, 1000)
    );

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    const { updateSetting, setUserPreferences } = settings_store;

    const lookup_function_store = useLookupFunctionStore();
    const { searchByField:autoTriggerSearchByField, interpolate }  = lookup_function_store;

    const doc_ms_data_lookup_store = useDocMasterDataLookUpStore();
    const {
    model: ms_view_model,
    advance_filters: ms_advance_filters,
    master_lookup_type,
    changed_fields,
    groups_to_update,
    selected_row: master_data_row,
    populate_row_to_view, master_data_fields_map,
    isDraggle,
    } = storeToRefs(doc_ms_data_lookup_store);
    const { resetMasterDataStore } = doc_ms_data_lookup_store;

    return {
      saveDocument,

      user_settings,
      updateSetting,
      remove_unmapped_columns,

      record,
      doctype,
      el,
      removeCache,
      isAI_TableExit,
      is_ai_table: ref(false),
      lineItemsloading: ref(true),
      tableColumns:ref(data),
      tableRows: ref(data),
      // record: ref(data),
      table_name: ref(''),
      lineDataObj: {} as dynamicObj,
      lovFieldsList: ref({} as dynamicObj),
      lineItemLayout: ref(data),
      formatting_options: ref(model),
      sortedTableColumns: ref([] as any),
      custom_columns_to_hide: ref(data),
      columns_to_hide: ref(data),
      layoutExtraColumns: ref([] as any),
      selectedRow: ref({} as any),
      fieldErros:  ref({} as any),
      selectedIndex: ref(),

      resetMasterDataStore,
      isDraggle,
      changed_fields,
      master_data_row,
      groups_to_update,
      master_lookup_type,
      ms_advance_filters,
      populate_row_to_view,
      master_data_fields_map,

      interpolate,
      autoTriggerSearchByField,
      lookup_loading_fields: ref({} as dynamicObj),
      master_data_popup_width: ref('700'),
      fuzzyDialog: ref(false),
      autoTriggerLookups: ref({} as dynamicObj),
      lookup_configurations: new Map(),
      autoTriggedFields: ref([] as any),
      debounceAutoTriggerFunc: {} as any,
    };
  }
});
</script>
