<template>
  <q-menu touch-position context-menu>
    <q-list dense style="min-width: 100px">
      <q-item clickable v-close-popup @click="setValueAsDefault()">
        <q-item-section>{{ $t('set_as_default') }}</q-item-section>
      </q-item>
      <q-separator />
      <q-item clickable v-close-popup>
        <q-item-section>{{ $t('close') }}</q-item-section>
      </q-item>
    </q-list>
  </q-menu>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { documentDetailApiService } from 'src/services';
export default defineComponent({
  name: 'select-as-default',
    props: {
    tableKey: {
      type: String,
      default: '',
    },
    columnName: {
      type: String,
      default: '',
    },
    attributeValue: {
      type: String,
      default: '',
    },
    doctype: {
      type: String,
      default: '',
    },
  },
  methods: {
    async setValueAsDefault() {
      if (!this.attributeValue) {
        return;
      }

      try {
        const formData = new FormData();
        formData.append('doc_type', this.doctype);
        formData.append('table_key', this.tableKey);
        formData.append('column_name', this.columnName);
        formData.append('attribute_name', 'UI_DEFAULT_VALUE');
        formData.append('attribute_value', this.attributeValue);
        formData.append('is_organization_default', 'true');

        await documentDetailApiService.setTableAdditionalAttribute(formData);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
  },
});
</script>
